import{_ as t,o as r,c as e,ae as i}from"./chunks/framework.D_KAhcqz.js";const l="/AI/llm-basic.png",o="/AI/llm-arch.png",m=JSON.parse('{"title":"大模型基础入门","description":"","frontmatter":{"layout":"doc","title":"大模型基础入门"},"headers":[],"relativePath":"articles/ai-base.md","filePath":"articles/ai-base.md"}'),n={name:"articles/ai-base.md"};function s(d,a,c,g,p,h){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="大模型基础入门" tabindex="-1">大模型基础入门 <a class="header-anchor" href="#大模型基础入门" aria-label="Permalink to &quot;大模型基础入门&quot;">​</a></h1><p>在人工智能技术飞速发展的今天，大语言模型已经成为 AI 应用落地的核心基础设施。无论是智能问答、内容生成、代码编写，还是复杂业务推理，大模型都在扮演着“大脑”的角色。对于开发者与学习者而言，掌握大模型基础原理与使用规范，是进入 AI 全栈开发的第一步。</p><h2 id="_1-大模型的基本定义" tabindex="-1">1. 大模型的基本定义 <a class="header-anchor" href="#_1-大模型的基本定义" aria-label="Permalink to &quot;1. 大模型的基本定义&quot;">​</a></h2><p>大语言模型（Large Language Model，LLM）是基于深度学习架构、在超大规模文本数据上进行预训练的语言模型。它通过学习海量语言规律、知识结构与逻辑模式，实现对人类语言的理解、生成与推理。</p><div style="text-align:center;margin:2rem 0;"><img src="'+l+'" alt="大模型基础架构" style="width:70%;border-radius:12px;"></div><p>与传统规则引擎或小模型不同，大模型具备极强的泛化能力，可以在不重新训练的情况下适配多种任务，如摘要、翻译、分类、创作、代码生成等，真正实现“一个模型适配多种场景”。</p><h2 id="_2-大模型核心技术架构" tabindex="-1">2. 大模型核心技术架构 <a class="header-anchor" href="#_2-大模型核心技术架构" aria-label="Permalink to &quot;2. 大模型核心技术架构&quot;">​</a></h2><p>现代大模型普遍基于 <strong>Transformer 架构</strong>构建，其核心是自注意力机制（Self-Attention），能够在处理文本时动态关注上下文之间的关联，从而实现更精准的语义理解。</p><p>模型训练通常分为两个阶段：</p><ol><li><strong>预训练</strong>：在海量公开数据上学习语言规律与世界知识</li><li><strong>微调与对齐</strong>：通过指令微调、人类反馈强化学习（RLHF）让模型更符合人类意图</li></ol><p>经过这两步，模型既能保证知识广度，又能具备稳定、安全、可用的输出能力。</p><div style="text-align:center;margin:2rem 0;"><img src="'+o+'" alt="Transformer架构简图" style="width:75%;border-radius:12px;"></div><h2 id="_3-关键基础概念" tabindex="-1">3. 关键基础概念 <a class="header-anchor" href="#_3-关键基础概念" aria-label="Permalink to &quot;3. 关键基础概念&quot;">​</a></h2><ul><li><strong>Token（分词）</strong>：模型处理文本的最小单位，中文通常 1 个字或半个词为一个 token</li><li><strong>上下文窗口</strong>：模型一次能“记住”的最大文本长度，决定对话与文档处理能力</li><li><strong>Prompt（提示词）</strong>：用户向模型下达的指令，是控制模型输出的核心手段</li><li><strong>Temperature（温度系数）</strong>：控制输出随机性，数值越低越稳定，越高越有创意</li><li><strong>幻觉（Hallucination）</strong>：模型编造不存在的事实，是大模型常见问题</li></ul><h2 id="_4-主流大模型对比" tabindex="-1">4. 主流大模型对比 <a class="header-anchor" href="#_4-主流大模型对比" aria-label="Permalink to &quot;4. 主流大模型对比&quot;">​</a></h2><p>目前国内外主流大模型各有侧重，适合不同场景：</p><ul><li><strong>GPT-4 / GPT-3.5</strong>：综合能力强，逻辑推理优秀</li><li><strong>通义千问</strong>：中文理解友好，适合国内业务场景</li><li><strong>文心一言</strong>：生态完善，支持多模态与工具调用</li><li><strong>Llama 2 / Mistral</strong>：开源可本地部署，适合私有化项目</li></ul><h2 id="_5-学习路径建议" tabindex="-1">5. 学习路径建议 <a class="header-anchor" href="#_5-学习路径建议" aria-label="Permalink to &quot;5. 学习路径建议&quot;">​</a></h2><p>想要系统掌握大模型开发，建议按以下路线学习：</p><ol><li>理解大模型基本原理与使用规范</li><li>掌握提示词工程，写出高效、稳定的 Prompt</li><li>学习 RAG、Agent 等上层应用技术</li><li>结合 LangChain 等框架搭建完整项目</li></ol><p>大模型时代已经到来，扎实的基础是后续实战开发的关键。</p><hr>',22)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
